/// Group (key, value) rows by key and summarize each group.
/// A row's key is normalized first: leading and trailing whitespace is
/// removed and ASCII letters are lowercased, so " Ab" and "aB" fall in the
/// same group "ab" (inner spaces are kept). Rows whose normalized key is
/// empty are ignored entirely.
/// For each group, return the tuple (key, count, total, mean, spread): the
/// normalized key, the number of rows, the sum of their values, the mean
/// rounded down toward negative infinity (so the mean of -1 and -2 is -2),
/// and the largest value minus the smallest.
/// Only groups with at least min_count rows are returned, sorted by total
/// descending, then by count descending, then by key ascending (plain
/// character order).
/// If min_count is less than 1, return None (even for empty rows).
/// >>> group_aggregate(vec![(String::from("a"), 3), (String::from("b"), 10), (String::from("A "), 4)], 1)
/// Some(vec![(String::from("b"), 1, 10, 10, 0), (String::from("a"), 2, 7, 3, 1)])
/// >>> group_aggregate(vec![(String::from("x"), -1), (String::from("x"), -2), (String::from("y"), 5)], 2)
/// Some(vec![(String::from("x"), 2, -3, -2, 1)])
fn group_aggregate(rows: Vec<(String, i64)>, min_count: i64) -> Option<Vec<(String, i64, i64, i64, i64)>> {
    if min_count < 1 {
        return None;
    }
    // groups in order of first appearance: (key, values)
    let mut groups: Vec<(String, Vec<i64>)> = Vec::new();
    for (key, value) in rows {
        let k = key.trim().to_ascii_lowercase();
        if k.is_empty() {
            continue;
        }
        match groups.iter_mut().find(|g| g.0 == k) {
            Some(g) => g.1.push(value),
            None => groups.push((k, vec![value])),
        }
    }
    let mut out: Vec<(String, i64, i64, i64, i64)> = Vec::new();
    for (k, vals) in groups {
        let count = vals.len() as i64;
        if count >= min_count {
            let total: i64 = vals.iter().sum();
            let spread = vals.iter().max().unwrap() - vals.iter().min().unwrap();
            out.push((k, count, total, total.div_euclid(count), spread));
        }
    }
    out.sort_by(|a, b| b.2.cmp(&a.2).then(b.1.cmp(&a.1)).then(a.0.cmp(&b.0)));
    Some(out)
}
